def parse_port(spec):
    parts = str(spec).split(":")
    proto = "tcp"
    if "/" in parts[-1]:
        tail = parts[-1].split("/")
        parts[-1] = tail[0]
        proto = tail[1]
    if len(parts) == 1:
        return ("0.0.0.0", None, int(parts[0]), proto)
    if len(parts) == 2:
        return ("0.0.0.0", int(parts[0]), int(parts[1]), proto)
    return (parts[0], int(parts[1]), int(parts[2]), proto)


def detect_conflict(services):
    used = {}
    conflicts = []
    for name in services:
        for p in services[name].get("ports") or []:
            ip, host, cont, proto = parse_port(p)
            if host is None:
                continue
            key = (ip, host, proto)
            if key in used:
                conflicts.append((used[key], name, ip, host, proto))
            else:
                used[key] = name
    return conflicts


