from collections import deque


def topo_or_cycle(graph):
    """graph: {服务名: [它依赖的服务...]}。边方向为 依赖 -> 被依赖者。

    无环时返回 (True, 拓扑序)；有环时返回 (False, 环内服务升序列表)。
    复杂度 O(V + E)。
    """
    indeg = {n: 0 for n in graph}
    adj = {n: [] for n in graph}
    for n, deps in graph.items():
        for d in deps:
            if d not in graph:
                continue          # 悬空依赖：不存在的服务，忽略或另行报错
            adj[d].append(n)
            indeg[n] += 1

    q = deque(sorted(n for n in graph if indeg[n] == 0))
    order = []
    while q:
        n = q.popleft()
        order.append(n)
        for m in sorted(adj[n]):
            indeg[m] -= 1
            if indeg[m] == 0:
                q.append(m)

    if len(order) == len(graph):
        return True, order
    return False, sorted(n for n in graph if indeg[n] > 0)


