def startup_batches(graph):
    """按入度分层：第 k 批 = 所有前驱都在前 k-1 批中的服务。

    无环时返回 (True, [[...], [...]])，每批内按字典序；有环时返回 (False, [])。
    """
    indeg = {n: 0 for n in graph}
    adj = {n: [] for n in graph}
    for n, deps in graph.items():
        for d in deps:
            if d not in graph:
                continue
            adj[d].append(n)
            indeg[n] += 1

    ready = sorted(n for n in graph if indeg[n] == 0)
    batches = []
    while ready:
        batches.append(list(ready))
        nxt = []
        for n in ready:
            for m in sorted(adj[n]):
                indeg[m] -= 1
                if indeg[m] == 0:
                    nxt.append(m)
        ready = sorted(nxt)

    if sum(len(b) for b in batches) != len(graph):
        return False, []
    return True, batches


